//! EPSG definitions that the bundled `crs-definitions` table lacks (about 1 200 codes: the CRSs
//! added to the registry since that crate was generated, and the 3D, geocentric and compound
//! ones it never listed), as PROJJSON.
//!
//! `crs_extra.bin` is generated by `test/reference/generate_crs_datum.py extra_table` from the
//! PROJ database (pyproj 3.8, PROJ 9.8): one `code<TAB>PROJJSON` line per CRS, minified, without
//! the free-text fields, deflate-compressed (1.5 MB of text, about 50 KB packed). It is inflated
//! on first use and kept for the life of the process. The definitions are read by the converter
//! in `crs_convert.rs` like any user-given PROJJSON, and written as such to GeoParquet. The EPSG
//! data are subject to the EPSG terms of use (see `NOTICE`).

use std::io::Read;
use std::sync::OnceLock;

use flate2::read::ZlibDecoder;
use serde_json::Value;

static PACKED: &[u8] = include_bytes!("crs_extra.bin");
const SCHEMA: &str = "https://proj.org/schemas/v0.7/projjson.schema.json";

struct Table {
    text: String,
    /// `(code, start, end)` of each JSON document in `text`, by code.
    index: Vec<(u32, usize, usize)>,
}

fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut text = String::new();
        ZlibDecoder::new(PACKED)
            .read_to_string(&mut text)
            .expect("crs_extra.bin is valid deflate data");
        let mut index = Vec::new();
        let mut at = 0;
        for line in text.split_inclusive('\n') {
            if let Some((code, _)) = line.split_once('\t') {
                if let Ok(code) = code.parse() {
                    let start = at + code_len(line);
                    index.push((code, start, at + line.trim_end().len()));
                }
            }
            at += line.len();
        }
        Table { text, index }
    })
}

/// Bytes up to and including the tab.
fn code_len(line: &str) -> usize {
    line.find('\t').map_or(0, |i| i + 1)
}

/// The PROJJSON of EPSG:`code`, when the supplementary table has it.
pub(crate) fn projjson(code: u32) -> Option<Value> {
    let table = table();
    let i = table
        .index
        .binary_search_by_key(&code, |(c, _, _)| *c)
        .ok()?;
    let (_, start, end) = table.index[i];
    let mut value: Value = serde_json::from_str(&table.text[start..end]).ok()?;
    if let Some(object) = value.as_object_mut() {
        // Insert the schema first, as pyproj writes it.
        let mut with_schema = serde_json::Map::new();
        with_schema.insert("$schema".into(), Value::from(SCHEMA));
        with_schema.append(object);
        return Some(Value::Object(with_schema));
    }
    Some(value)
}

/// The codes of the supplementary table.
#[cfg(test)]
pub(crate) fn codes() -> Vec<u32> {
    table().index.iter().map(|(c, _, _)| *c).collect()
}
